def islands(grid: list[str]) -> int:
    if not grid:
        return 0

    rows = len(grid)
    cols = max(len(row) for row in grid)
    visited = [[False] * cols for _ in range(rows)]
    count = 0

    for r in range(rows):
        for c in range(cols):
            if c < len(grid[r]) and grid[r][c] == '1' and not visited[r][c]:
                count += 1
                stack = [(r, c)]
                visited[r][c] = True

                while stack:
                    i, j = stack.pop()

                    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ni, nj = i + di, j + dj

                        if (
                            0 <= ni < rows
                            and 0 <= nj < len(grid[ni])
                            and grid[ni][nj] == '1'
                            and not visited[ni][nj]
                        ):
                            visited[ni][nj] = True
                            stack.append((ni, nj))

    return count
```

